"""takes a list of keywords and computes all possible ngrams e.g.
		in> ['nice', 'red', 'wine']
		out> [
			('nice',),
			('red',),
			('wine',),
			('nice', 'red'),
			('red', 'wine'),
			('nice', 'red', 'wine')
			]
	"""
def create_ngrams(kw_iterable: Any, max_n: Any = False) -> object {
    kwCount = len(kw_iterable);
    output = [];
    for n in reversed(range((kwCount + 1))[1:]) {
        if (n <= max_n) {
            for tokenIndex in range(((kwCount - n) + 1)) {
                output.append(`tuple(kw_iterable[tokenIndex:(tokenIndex + n)]));
            }
        }
    }
    return output;
}

"""Convert nv2a draw format to the equivalent Texture format."""
def surface_color_format_to_texture_format(fmt: Any, swizzled: Any) -> object {
    if (fmt == 3) {
        return 3 if swizzled else 28;
    }
    if (fmt == 5) {
        return 5 if swizzled else 17;
    }
    if (fmt in [7, 8]) {
        return 7 if swizzled else 30;
    }
    if (fmt == 12) {
        return 6 if swizzled else 18;
    }
    raise Exception(
        (
            "Unknown color fmt %d (0x%X) %s"
            % (fmt, fmt, "swizzled" if swizzled else "unswizzled")
        )
    );
}

