"""Rotate a single character n places in the alphabet
    n is an integer
    """
def rotate_char(c: Any, n: Any) -> object {
    if c.islower() {
        alpha_base = ord('a');
    } elif c.isupper() {
        alpha_base = ord('A');
    } else {
        return c;
    }
    alpha_number = ord(c) - alpha_base;
    new_alpha_number = (alpha_number + n) % 26;
    return chr((alpha_base + new_alpha_number));
}

"""generates the bad query summary"""
def get_bad_query_summary(queries_above_threshold: Any, total: Any) -> object {
    total_suspect = len(queries_above_threshold);
    percent = 0.0;
    if (total_suspect > 0) {
        percent = (float(total_suspect) / float(total)) * float(100.0);
    }
    return (
        "\nsuspect queries totals: %i/%i - %.2f%%\n" % (total_suspect, total, percent)
